import { ResumeSpec } from '../schemas/resume.js';
import { PrivacyRulesConfig } from '../schemas/privacy.js';
import { redactText } from '../integrity/redaction-engine.js';

function redact(text: string, rules?: PrivacyRulesConfig): string {
  const effectiveRules: PrivacyRulesConfig = rules
    ? {
        strip_patterns: rules.strip_patterns ?? [],
        replacements: rules.replacements ?? [],
        banned_keywords: rules.banned_keywords ?? [],
      }
    : { strip_patterns: [], replacements: [], banned_keywords: [] };
  return redactText(text, effectiveRules).redactedText;
}

/**
 * Compiles a ResumeSpec into clean ATS-friendly plaintext/markdown.
 * Automatically redacts citation tags (ev-###), internal ticket IDs,
 * and sensitive terms via redactText.
 */
export function compileMarkdownResume(spec: ResumeSpec, rules?: PrivacyRulesConfig): string {
  const sections: string[] = [];

  // Header
  const name = redact(spec.profile.name, rules);
  const title = redact(spec.profile.title, rules);

  const contactItems: string[] = [];
  contactItems.push(redact(spec.profile.email, rules));
  if (spec.profile.phone) {
    contactItems.push(redact(spec.profile.phone, rules));
  }
  if (spec.profile.location) {
    contactItems.push(redact(spec.profile.location, rules));
  }

  if (spec.profile.links) {
    for (const [, url] of Object.entries(spec.profile.links)) {
      if (url) {
        contactItems.push(redact(url, rules));
      }
    }
  }

  sections.push(`# ${name}\n${title}\n\n${contactItems.join(' | ')}`);

  // Summary
  if (spec.summary && spec.summary.trim()) {
    const cleanSummary = redact(spec.summary, rules);
    sections.push(`## Summary\n${cleanSummary}`);
  }

  // Experience
  if (spec.experiences && spec.experiences.length > 0) {
    const expLines: string[] = ['## Experience'];
    for (const exp of spec.experiences) {
      const company = redact(exp.company, rules);
      const role = redact(exp.role, rules);
      const location = exp.location ? redact(exp.location, rules) : '';
      const dateLoc = location
        ? `${exp.startDate} - ${exp.endDate} | ${location}`
        : `${exp.startDate} - ${exp.endDate}`;

      expLines.push(`### ${role} - ${company}\n${dateLoc}`);

      for (const bullet of exp.bullets) {
        const cleanBullet = redact(bullet.text, rules);
        expLines.push(`- ${cleanBullet}`);
      }
    }
    sections.push(expLines.join('\n\n'));
  }

  // Education
  if (spec.education && spec.education.length > 0) {
    const eduLines: string[] = ['## Education'];
    for (const edu of spec.education) {
      const institution = redact(edu.institution, rules);
      const degree = redact(edu.degree, rules);
      const details = edu.details ? redact(edu.details, rules) : '';

      const line = details ? `${edu.year}\n${details}` : `${edu.year}`;
      eduLines.push(`### ${degree} - ${institution}\n${line}`);
    }
    sections.push(eduLines.join('\n\n'));
  }

  // Skills
  if (spec.skills && spec.skills.length > 0) {
    const skillLines: string[] = ['## Skills'];
    for (const group of spec.skills) {
      const category = redact(group.category, rules);
      const skillList = group.skills.map((s) => redact(s, rules)).join(', ');
      skillLines.push(`- **${category}**: ${skillList}`);
    }
    sections.push(skillLines.join('\n'));
  }

  return sections.join('\n\n').trim() + '\n';
}

import { z } from 'zod';

/**
 * Data contracts for staged, skill-driven resume tailoring runs.
 *
 * Each gate has two shapes:
 * - a *model output* shape (what a runner must return; mirrored by a strict JSON Schema)
 * - a *stored* shape (model output plus user edits, decisions, and validation annotations)
 */

export const TAILORING_STEPS = ['analysis', 'alignment', 'proposals', 'brief'] as const;
export type TailoringStep = (typeof TAILORING_STEPS)[number];

// ---------------------------------------------------------------------------
// Gate 0: Job analysis
// ---------------------------------------------------------------------------

export const RequirementTierSchema = z.enum(['must', 'nice', 'vocabulary']);
export type RequirementTier = z.infer<typeof RequirementTierSchema>;

export const JobRequirementSchema = z.object({
  id: z.string().min(1),
  tier: RequirementTierSchema,
  text: z.string().min(1),
  quote: z.string(),
  /** Concrete technologies/tools/domain terms named by this requirement (e.g. "Kafka"). */
  terms: z.array(z.string()).default([]),
  /** Set by validation: quote could not be found in the posting. */
  ungrounded: z.boolean().optional(),
});
export type JobRequirement = z.infer<typeof JobRequirementSchema>;

export const JobAnalysisSchema = z.object({
  company: z.string(),
  role: z.string(),
  seniority: z.string(),
  mission: z.string(),
  requirements: z.array(JobRequirementSchema),
  boilerplate: z.array(z.string()).default([]),
});
export type JobAnalysis = z.infer<typeof JobAnalysisSchema>;

// ---------------------------------------------------------------------------
// Gate 1: Alignment matrix
// ---------------------------------------------------------------------------

export const AlignmentClassificationSchema = z.enum(['backed', 'transferable', 'gap']);
export type AlignmentClassification = z.infer<typeof AlignmentClassificationSchema>;

export const ValidationIssueSchema = z.object({
  severity: z.enum(['block', 'warn']),
  kind: z.string(),
  message: z.string(),
});
export type ValidationIssue = z.infer<typeof ValidationIssueSchema>;

export const AlignmentRowSchema = z.object({
  requirement_id: z.string().min(1),
  classification: AlignmentClassificationSchema,
  citations: z.array(z.string()).default([]),
  rationale: z.string().default(''),
  adjacent_tool: z.string().default(''),
  candidate_confirmed: z.boolean().default(false),
  issues: z.array(ValidationIssueSchema).optional(),
});
export type AlignmentRow = z.infer<typeof AlignmentRowSchema>;

export const AlignmentMatrixSchema = z.object({
  rows: z.array(AlignmentRowSchema),
});
export type AlignmentMatrix = z.infer<typeof AlignmentMatrixSchema>;

// ---------------------------------------------------------------------------
// Gate 2: Proposals
// ---------------------------------------------------------------------------

export const PROPOSAL_TYPES = [
  'summary.rewrite',
  'bullet.rewrite',
  'bullet.add',
  'bullet.drop',
  'bullet.reorder',
  'skills.reorder',
  'skills.prune',
] as const;
export const ProposalTypeSchema = z.enum(PROPOSAL_TYPES);
export type ProposalType = z.infer<typeof ProposalTypeSchema>;

export const ProposalTargetSchema = z.object({
  /** Index into base resume `experiences`, or -1 when not applicable. */
  experience_index: z.number().int().default(-1),
  /** Index into that experience's original `bullets` (insert position for bullet.add), or -1. */
  bullet_index: z.number().int().default(-1),
  /** Index into base resume `skills` groups, or -1. */
  skill_group_index: z.number().int().default(-1),
});
export type ProposalTarget = z.infer<typeof ProposalTargetSchema>;

export const ProposalDecisionSchema = z.enum(['pending', 'accepted', 'rejected']);
export type ProposalDecision = z.infer<typeof ProposalDecisionSchema>;

export const ProposalSchema = z.object({
  id: z.string().min(1),
  type: ProposalTypeSchema,
  target: ProposalTargetSchema,
  before: z.string().default(''),
  after: z.string().default(''),
  /** bullet.reorder: permutation of original bullet indices. */
  order: z.array(z.number().int()).default([]),
  /** skills.reorder: full new ordering; skills.prune: skills to remove. */
  skills: z.array(z.string()).default([]),
  citations: z.array(z.string()).default([]),
  requirement_ids: z.array(z.string()).default([]),
  rationale: z.string().default(''),
  decision: ProposalDecisionSchema.default('pending'),
  /** User-edited replacement for `after`. */
  edited_after: z.string().optional(),
  checks: z.array(ValidationIssueSchema).default([]),
});
export type Proposal = z.infer<typeof ProposalSchema>;

export const ProposalSetSchema = z.object({
  proposals: z.array(ProposalSchema),
});
export type ProposalSet = z.infer<typeof ProposalSetSchema>;

// ---------------------------------------------------------------------------
// Gate 3: Interview defensibility brief
// ---------------------------------------------------------------------------

export const DefensibilityBriefSchema = z.object({
  anchor_stories: z
    .array(
      z.object({
        title: z.string(),
        problem: z.string(),
        ownership: z.string(),
        proof: z.string(),
        citations: z.array(z.string()).default([]),
      })
    )
    .default([]),
  bridges: z
    .array(
      z.object({
        requirement_id: z.string(),
        adjacent_tool: z.string(),
        framing: z.string(),
      })
    )
    .default([]),
  gaps: z
    .array(
      z.object({
        requirement_id: z.string(),
        acknowledgement: z.string(),
        parallel_mastery: z.string(),
      })
    )
    .default([]),
});
export type DefensibilityBrief = z.infer<typeof DefensibilityBriefSchema>;

// ---------------------------------------------------------------------------
// Run manifest
// ---------------------------------------------------------------------------

export const RunStateSchema = z.enum([
  'draft',
  'analyzing',
  'analysis_ready',
  'aligning',
  'alignment_review',
  'proposing',
  'proposal_review',
  'briefing',
  'complete',
  'error',
  'cancelled',
]);
export type RunState = z.infer<typeof RunStateSchema>;

export const StepStatusSchema = z.enum(['pending', 'running', 'done', 'approved', 'stale', 'error']);
export type StepStatus = z.infer<typeof StepStatusSchema>;

export const StepRecordSchema = z.object({
  status: StepStatusSchema.default('pending'),
  completed_at: z.string().nullable().default(null),
  input_hash: z.string().nullable().default(null),
  error: z.string().nullable().default(null),
  raw_output: z.string().nullable().default(null),
});
export type StepRecord = z.infer<typeof StepRecordSchema>;

export const RunManifestSchema = z.object({
  slug: z.string().min(1),
  title: z.string().default(''),
  created: z.string(),
  updated: z.string(),
  runner: z.string(),
  model: z.string().default(''),
  base_resume: z.string(),
  state: RunStateSchema,
  error: z.string().nullable().default(null),
  finalized_path: z.string().nullable().default(null),
  steps: z.object({
    analysis: StepRecordSchema,
    alignment: StepRecordSchema,
    proposals: StepRecordSchema,
    brief: StepRecordSchema,
  }),
});
export type RunManifest = z.infer<typeof RunManifestSchema>;

// ---------------------------------------------------------------------------
// Strict JSON Schemas handed to runners (structured output).
// All properties required + additionalProperties:false for provider compatibility.
// ---------------------------------------------------------------------------

type JsonSchema = Record<string, unknown>;

const str: JsonSchema = { type: 'string' };
const strArr: JsonSchema = { type: 'array', items: { type: 'string' } };
const intArr: JsonSchema = { type: 'array', items: { type: 'integer' } };

function obj(properties: Record<string, JsonSchema>): JsonSchema {
  return {
    type: 'object',
    properties,
    required: Object.keys(properties),
    additionalProperties: false,
  };
}

export const JOB_ANALYSIS_JSON_SCHEMA: JsonSchema = obj({
  company: str,
  role: str,
  seniority: str,
  mission: str,
  requirements: {
    type: 'array',
    items: obj({
      id: str,
      tier: { type: 'string', enum: ['must', 'nice', 'vocabulary'] },
      text: str,
      quote: str,
      terms: strArr,
    }),
  },
  boilerplate: strArr,
});

export const ALIGNMENT_JSON_SCHEMA: JsonSchema = obj({
  rows: {
    type: 'array',
    items: obj({
      requirement_id: str,
      classification: { type: 'string', enum: ['backed', 'transferable', 'gap'] },
      citations: strArr,
      rationale: str,
      adjacent_tool: str,
    }),
  },
});

export const PROPOSALS_JSON_SCHEMA: JsonSchema = obj({
  proposals: {
    type: 'array',
    items: obj({
      id: str,
      type: { type: 'string', enum: [...PROPOSAL_TYPES] },
      target: obj({
        experience_index: { type: 'integer' },
        bullet_index: { type: 'integer' },
        skill_group_index: { type: 'integer' },
      }),
      before: str,
      after: str,
      order: intArr,
      skills: strArr,
      citations: strArr,
      requirement_ids: strArr,
      rationale: str,
    }),
  },
});

export const BRIEF_JSON_SCHEMA: JsonSchema = obj({
  anchor_stories: {
    type: 'array',
    items: obj({ title: str, problem: str, ownership: str, proof: str, citations: strArr }),
  },
  bridges: {
    type: 'array',
    items: obj({ requirement_id: str, adjacent_tool: str, framing: str }),
  },
  gaps: {
    type: 'array',
    items: obj({ requirement_id: str, acknowledgement: str, parallel_mastery: str }),
  },
});

export const STEP_JSON_SCHEMAS: Record<TailoringStep, JsonSchema> = {
  analysis: JOB_ANALYSIS_JSON_SCHEMA,
  alignment: ALIGNMENT_JSON_SCHEMA,
  proposals: PROPOSALS_JSON_SCHEMA,
  brief: BRIEF_JSON_SCHEMA,
};

import fs from 'node:fs';
import path from 'node:path';
import pc from 'picocolors';
import {
  lintCitations,
  validateMetrics,
  redactText,
  auditSlop,
  SLOP_WEIGHTS,
  SlopMatch,
} from '@featherduster/core';
import {
  findFiles,
  loadEvidenceStore,
  loadPrivacyRules,
} from '../server.js';

export interface CheckIssue {
  file: string;
  type:
    | 'dangling_citation'
    | 'missing_metric'
    | 'provisional_evidence'
    | 'retracted_evidence'
    | 'banned_keyword'
    | 'ai_slop'
    | 'slop';
  severity?: 'error' | 'warning';
  message: string;
  line?: number;
  citation?: string;
  keyword?: string;
  slopMatch?: SlopMatch;
}

export interface CheckResult {
  isClean: boolean;
  issues: CheckIssue[];
  errors: CheckIssue[];
  warnings: CheckIssue[];
  totalFiles: number;
  validCitationsCount: number;
  danglingCitationsCount: number;
  slopMatchesCount: number;
  provisionalCitationsCount: number;
}

export interface CheckWorkspaceOptions {
  strict?: boolean;
}

/**
 * Checks integrity of citations, metrics, and privacy rules across a workspace.
 */
export function checkWorkspace(workspaceDir: string, options?: CheckWorkspaceOptions): CheckResult {
  const resolvedDir = path.resolve(workspaceDir);
  const store = loadEvidenceStore(resolvedDir);
  const privacyRules = loadPrivacyRules(resolvedDir);

  const candidateDirs = [
    path.join(resolvedDir, 'resumes'),
    path.join(resolvedDir, 'evidence'),
    path.join(resolvedDir, 'rubrics'),
    path.join(resolvedDir, 'companies'),
  ];

  const filesToCheck: string[] = [];
  try {
    const rootEntries = fs.readdirSync(resolvedDir, { withFileTypes: true });
    for (const entry of rootEntries) {
      const lower = entry.name.toLowerCase();
      if (
        entry.isFile() &&
        (lower.endsWith('.md') || lower.endsWith('.markdown')) &&
        !lower.startsWith('agent') &&
        !lower.startsWith('readme') &&
        !lower.startsWith('contributing') &&
        !lower.startsWith('changelog')
      ) {
        filesToCheck.push(path.join(resolvedDir, entry.name));
      }
    }
  } catch {
    // Ignore error reading root directory
  }

  for (const dir of candidateDirs) {
    filesToCheck.push(
      ...findFiles(dir, ['.md', '.markdown', '.txt', '.tex', '.typ', '.yaml', '.yml'])
    );
  }

  const issues: CheckIssue[] = [];
  let validCitationsCount = 0;
  let danglingCitationsCount = 0;
  let slopMatchesCount = 0;

  for (const file of filesToCheck) {
    const relativePath = path.relative(resolvedDir, file).replace(/\\/g, '/');
    const baseName = path.basename(file).toLowerCase();
    const isLedgerFile = baseName.startsWith('evidence-ledger');

    try {
      const content = fs.readFileSync(file, 'utf-8');

      // 1. Citation & Metric verification (skip self-check on the canonical evidence ledger)
      if (!isLedgerFile) {
        const citationResult = lintCitations(content, store);
        validCitationsCount += citationResult.validCitations.length;
        danglingCitationsCount += citationResult.danglingCitations.length;

        for (const dangling of citationResult.danglingCitations) {
          issues.push({
            file: relativePath,
            type: 'dangling_citation',
            severity: 'error',
            message: `Dangling citation '${dangling}' cannot be resolved to any evidence entry`,
            citation: dangling,
          });
        }

        // 2. Metric verification
        const metricResult = validateMetrics(content, store);
        for (const mIssue of metricResult.issues) {
          const isWarning = mIssue.type === 'provisional_evidence' && !options?.strict;
          issues.push({
            file: relativePath,
            type: mIssue.type,
            severity: isWarning ? 'warning' : 'error',
            message: mIssue.message,
            line: mIssue.line,
          });
        }
      }

      // 3. Privacy / banned keyword verification
      if (privacyRules.banned_keywords && privacyRules.banned_keywords.length > 0) {
        const redactResult = redactText(content, privacyRules);
        for (const violation of redactResult.violations) {
          issues.push({
            file: relativePath,
            type: 'banned_keyword',
            severity: 'error',
            message: `Banned keyword '${violation}' detected in content`,
            keyword: violation,
          });
        }
      }

      // 4. AI Slop & Buzzword Audit across evidence and resume markdown files
      const isEvidenceOrResume =
        (relativePath.startsWith('evidence/') ||
          relativePath.startsWith('resumes/') ||
          relativePath.includes('/evidence/') ||
          relativePath.includes('/resumes/')) &&
        (file.endsWith('.md') || file.endsWith('.markdown'));

      if (isEvidenceOrResume) {
        const slopResult = auditSlop(content);
        slopMatchesCount += slopResult.matches.length;

        // Collect slop issues: matches with high or moderate severity (weight >= 2) or moderate/high slop band
        const severeMatches = slopResult.matches.filter(
          (m) =>
            (SLOP_WEIGHTS[m.type] ?? 1) >= 2 ||
            slopResult.slopBand === 'moderate' ||
            slopResult.slopBand === 'high'
        );

        for (const match of severeMatches) {
          issues.push({
            file: relativePath,
            type: 'ai_slop',
            severity: 'error',
            message: `AI slop / buzzword pattern '${match.matchedText}' (${match.patternName}) detected`,
            line: match.line,
            slopMatch: match,
          });
        }
      }
    } catch {
      // Ignore unreadable file
    }
  }

  const errors = issues.filter((i) => (i.severity ?? 'error') === 'error');
  const warnings = issues.filter((i) => i.severity === 'warning');
  const provisionalCitationsCount = warnings.filter((w) => w.type === 'provisional_evidence').length;

  return {
    isClean: errors.length === 0,
    issues,
    errors,
    warnings,
    totalFiles: filesToCheck.length,
    validCitationsCount,
    danglingCitationsCount,
    slopMatchesCount,
    provisionalCitationsCount,
  };
}

/**
 * Formats and prints the colored integrity report to stdout/stderr.
 */
export function printCheckReport(result: CheckResult): void {
  console.log('\n' + pc.bold(pc.cyan('Featherduster Integrity Audit')) + '\n');

  if (result.isClean) {
    console.log(
      pc.green(`✔ [PASS] Integrity check passed! 0 violations found across ${result.totalFiles} files.`)
    );
    console.log(pc.gray(`  • ${result.validCitationsCount} valid citation(s) verified against evidence store.`));
    console.log(pc.gray(`  • 0 unverified or missing metric tokens.`));
    console.log(pc.gray(`  • 0 banned keyword leaks detected.`));
    console.log(pc.gray(`  • ${result.slopMatchesCount} AI slop / buzzword filler patterns detected.`));
    if (result.provisionalCitationsCount > 0) {
      console.log(pc.gray(`  • ${result.provisionalCitationsCount} provisional citation(s) in flight (advisory).`));
    }
    console.log('');
  } else {
    console.log(
      pc.red(
        `✖ [FAIL] Integrity check failed with ${result.errors.length} violation(s) across ${result.totalFiles} files:\n`
      )
    );
    console.log(pc.gray(`  • ${result.validCitationsCount} valid citation(s) verified against evidence store.`));
    if (result.danglingCitationsCount > 0) {
      console.log(pc.red(`  • ${result.danglingCitationsCount} dangling citation(s) detected.`));
    }
    const slopText = `  • ${result.slopMatchesCount} AI slop / buzzword filler patterns detected.`;
    console.log(result.slopMatchesCount > 0 ? pc.yellow(slopText) : pc.gray(slopText));
    if (result.provisionalCitationsCount > 0) {
      console.log(pc.gray(`  • ${result.provisionalCitationsCount} provisional citation(s) in flight (advisory).`));
    }
    console.log('');

    for (const issue of result.errors) {
      const sanitizedFile = issue.file.replace(/\x1b\[[0-9;]*m/g, '');
      const sanitizedMessage = issue.message.replace(/\x1b\[[0-9;]*m/g, '');
      const location = issue.line
        ? `${pc.yellow(sanitizedFile)}:${pc.cyan(String(issue.line))}`
        : pc.yellow(sanitizedFile);

      const tag =
        issue.type === 'ai_slop' || issue.type === 'slop'
          ? pc.bgYellow(pc.black(` SLOP `))
          : pc.bgRed(pc.black(` ${issue.type.toUpperCase()} `));
      console.log(`  ${tag} ${location}`);
      console.log(`    ${pc.red(sanitizedMessage)}\n`);
    }
  }
}

export interface RunCheckOptions {
  workspace?: string;
  exitOnError?: boolean;
  strict?: boolean;
}

/**
 * Headless CLI check command handler.
 */
export async function runCheckCommand(options?: RunCheckOptions): Promise<CheckResult> {
  const workspaceDir = options?.workspace || process.cwd();
  const result = checkWorkspace(workspaceDir, { strict: options?.strict });
  printCheckReport(result);

  if (options?.exitOnError !== false) {
    process.exit(result.isClean ? 0 : 1);
  }

  return result;
}

